Class Employee
  Define name As String;

  Method Constructor(n As String)
    This.name <- n;
  EndMethod

  Method Introduce() As String
    Return "Hello, I am " + This.name;
  EndMethod
EndClass

Class Cashier Inherits From Employee
  Method Constructor(n As String)
    Super.constructor(n);
  EndMethod

  Method Introduce() As String
    Return Super.Introduce() + " and I work the till";
  EndMethod
EndClass

Algorithm Kiosk
  Define ana As Employee <- New Employee("Ana");
  Define beto As Employee <- New Cashier("Beto");
  Write ana.Introduce();
  Write beto.Introduce();
EndAlgorithm

Class Offer
  Define percent As Integer;
  Method Constructor(p As Integer)
    This.percent <- p;
  EndMethod
  Method Apply(price As Integer) As Integer
    Return price - price * This.percent Div 100;
  EndMethod
EndClass

Class Expiry
  Define days As Integer;
  Method Constructor(d As Integer)
    This.days <- d;
  EndMethod
  Method Apply(price As Integer) As Integer
    If This.days <= 2 Then
      Return price Div 2;
    EndIf
    Return price;
  EndMethod
EndClass

Class Product
  Define name As String;
  Define price As Integer;
  Define offer As Offer;
  Define expiry As Expiry;
  Method Constructor(n As String, p As Integer)
    This.name <- n;
    This.price <- p;
    This.offer <- New Offer(0);
    This.expiry <- New Expiry(365);
  EndMethod
  Method SetOffer(newOffer As Offer)
    This.offer <- newOffer;
  EndMethod
  Method SetExpiry(date As Expiry)
    This.expiry <- date;
  EndMethod
  Method FinalPrice() As Integer
    Return This.expiry.Apply(This.offer.Apply(This.price));
  EndMethod
EndClass

Algorithm Kiosk
  Define juice As Product <- New Product("Juice", 30);
  Define milk As Product <- New Product("Milk", 40);
  milk.SetExpiry(New Expiry(1));
  Define biscuits As Product <- New Product("Biscuits", 20);
  biscuits.SetOffer(New Offer(50));
  Define yoghurt As Product <- New Product("Yoghurt", 40);
  yoghurt.SetOffer(New Offer(25));
  yoghurt.SetExpiry(New Expiry(1));
  Write juice.name, " ", juice.FinalPrice();
  Write milk.name, " ", milk.FinalPrice();
  Write biscuits.name, " ", biscuits.FinalPrice();
  Write yoghurt.name, " ", yoghurt.FinalPrice();
EndAlgorithm
